ALTER TABLE licenses ADD COLUMN notes TEXT NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS audit_at ON audit(at);
CREATE INDEX IF NOT EXISTS audit_action_id ON audit(action,id);
CREATE TABLE IF NOT EXISTS admin_security(id INTEGER PRIMARY KEY CHECK(id=1),secret TEXT,pending TEXT,pending_until INTEGER NOT NULL DEFAULT 0,pending_owner TEXT,version INTEGER NOT NULL DEFAULT 0,last_step INTEGER NOT NULL DEFAULT -1);
INSERT OR IGNORE INTO admin_security(id) VALUES(1);
CREATE TABLE IF NOT EXISTS admin_recovery(hash TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS admin_enrollments(id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS admin_batches(id TEXT PRIMARY KEY,payload_hash TEXT NOT NULL,result TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reminder_config(id INTEGER PRIMARY KEY CHECK(id=1),channel TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',last_run INTEGER);
INSERT OR IGNORE INTO reminder_config(id) VALUES(1);
CREATE TABLE IF NOT EXISTS license_reminders(license_id TEXT NOT NULL REFERENCES licenses(id) ON DELETE CASCADE,expires INTEGER NOT NULL,stage INTEGER NOT NULL,state TEXT NOT NULL,attempt INTEGER NOT NULL,PRIMARY KEY(license_id,expires,stage));
